fn tree_run_limits(
    current_len: ::core::ffi::c_int,
    next_len: ::core::ffi::c_int,
) -> (::core::ffi::c_int, ::core::ffi::c_int) {
    if next_len == 0 {
        (138, 3)
    } else if current_len == next_len {
        (6, 3)
    } else {
        (7, 4)
    }
}

fn initial_tree_run_state(
    first_length: ::core::ffi::c_int,
) -> (
    ::core::ffi::c_int,
    ::core::ffi::c_int,
    ::core::ffi::c_int,
    ::core::ffi::c_int,
) {
    let (max_count, min_count) = tree_run_limits(0, first_length);
    (-1, 0, max_count, min_count)
}

fn tree_run_continues(
    count: ::core::ffi::c_int,
    max_count: ::core::ffi::c_int,
    current_len: ::core::ffi::c_int,
    next_len: ::core::ffi::c_int,
) -> bool {
    count < max_count && current_len == next_len
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
enum ScanTreeAction {
    LiteralCount(crate::zutil_h::ush),
    RepeatLength { emit_length_once: bool },
    RepeatZeroShort,
    RepeatZeroLong,
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
struct TreeRunStep {
    action: Option<ScanTreeAction>,
    count: ::core::ffi::c_int,
    previous_len: ::core::ffi::c_int,
    max_count: ::core::ffi::c_int,
    min_count: ::core::ffi::c_int,
}

fn classify_tree_run(
    count: ::core::ffi::c_int,
    min_count: ::core::ffi::c_int,
    current_len: ::core::ffi::c_int,
    previous_len: ::core::ffi::c_int,
) -> ScanTreeAction {
    if count < min_count {
        ScanTreeAction::LiteralCount(count as crate::zutil_h::ush)
    } else if current_len != 0 {
        ScanTreeAction::RepeatLength {
            emit_length_once: current_len != previous_len,
        }
    } else if count <= 10 {
        ScanTreeAction::RepeatZeroShort
    } else {
        ScanTreeAction::RepeatZeroLong
    }
}

fn tree_run_step(
    count: ::core::ffi::c_int,
    max_count: ::core::ffi::c_int,
    min_count: ::core::ffi::c_int,
    current_len: ::core::ffi::c_int,
    next_len: ::core::ffi::c_int,
    previous_len: ::core::ffi::c_int,
) -> TreeRunStep {
    if tree_run_continues(count, max_count, current_len, next_len) {
        return TreeRunStep {
            action: None,
            count,
            previous_len,
            max_count,
            min_count,
        };
    }

    let action = classify_tree_run(count, min_count, current_len, previous_len);
    let (max_count, min_count) = tree_run_limits(current_len, next_len);
    TreeRunStep {
        action: Some(action),
        count: 0,
        previous_len: current_len,
        max_count,
        min_count,
    }
}

fn tree_run_step_after_increment(
    count: ::core::ffi::c_int,
    max_count: ::core::ffi::c_int,
    min_count: ::core::ffi::c_int,
    current_len: ::core::ffi::c_int,
    next_len: ::core::ffi::c_int,
    previous_len: ::core::ffi::c_int,
) -> (::core::ffi::c_int, TreeRunStep) {
    let count = count + 1;
    (
        count,
        tree_run_step(
            count,
            max_count,
            min_count,
            current_len,
            next_len,
            previous_len,
        ),
    )
}

fn tally_scan_tree_action(
    bl_tree: &mut [crate::src::deflate::ct_data],
    current_len: ::core::ffi::c_int,
    action: ScanTreeAction,
) {
    match action {
        ScanTreeAction::LiteralCount(literal_count) => {
            bl_tree[current_len as usize].fc.value =
                (bl_tree[current_len as usize].fc.value as ::core::ffi::c_int
                    + literal_count as ::core::ffi::c_int) as crate::zutil_h::ush;
        }
        ScanTreeAction::RepeatLength { emit_length_once } => {
            if emit_length_once {
                bl_tree[current_len as usize].fc.value =
                    bl_tree[current_len as usize].fc.value.wrapping_add(1);
            }
            bl_tree[REP_3_6 as usize].fc.value = bl_tree[REP_3_6 as usize].fc.value.wrapping_add(1);
        }
        ScanTreeAction::RepeatZeroShort => {
            bl_tree[REPZ_3_10 as usize].fc.value =
                bl_tree[REPZ_3_10 as usize].fc.value.wrapping_add(1);
        }
        ScanTreeAction::RepeatZeroLong => {
            bl_tree[REPZ_11_138 as usize].fc.value =
                bl_tree[REPZ_11_138 as usize].fc.value.wrapping_add(1);
        }
    }
}

fn tree_run_extra_bits(
    action: ScanTreeAction,
    count: ::core::ffi::c_int,
) -> Option<(::core::ffi::c_int, ::core::ffi::c_int)> {
    match action {
        ScanTreeAction::LiteralCount(_) => None,
        ScanTreeAction::RepeatLength { .. } => Some((count - 3, 2)),
        ScanTreeAction::RepeatZeroShort => Some((count - 3, 3)),
        ScanTreeAction::RepeatZeroLong => Some((count - 11, 7)),
    }
}

fn tree_next_cursor(index: ::core::ffi::c_int) -> usize {
    index.wrapping_add(1) as usize
}

fn bl_code_index_at_rank(rank: ::core::ffi::c_int) -> usize {
    bl_order[rank as usize] as usize
}

fn last_nonzero_bl_tree_rank(code_lengths: &[crate::zutil_h::ush]) -> ::core::ffi::c_int {
    let mut rank = crate::src::deflate::BL_CODES - 1 as ::core::ffi::c_int;
    while rank >= 3 as ::core::ffi::c_int
        && code_lengths[bl_code_index_at_rank(rank)] == 0 as crate::zutil_h::ush
    {
        rank -= 1;
    }
    rank
}

fn bl_tree_header_bit_length(max_blindex: ::core::ffi::c_int) -> crate::zutil_h::ulg {
    (3 as crate::zutil_h::ulg)
        .wrapping_mul((max_blindex as crate::zutil_h::ulg).wrapping_add(1))
        .wrapping_add(5)
        .wrapping_add(5)
        .wrapping_add(4)
}

fn bl_tree_header_cost_update(
    opt_len: crate::zutil_h::ulg,
    max_blindex: ::core::ffi::c_int,
) -> crate::zutil_h::ulg {
    opt_len.wrapping_add(bl_tree_header_bit_length(max_blindex))
}

fn bl_tree_header_update(
    code_lengths: &[crate::zutil_h::ush; BL_CODE_ORDER_LEN],
    opt_len: crate::zutil_h::ulg,
) -> (::core::ffi::c_int, crate::zutil_h::ulg) {
    let max_blindex = last_nonzero_bl_tree_rank(code_lengths);
    (
        max_blindex,
        bl_tree_header_cost_update(opt_len, max_blindex),
    )
}

unsafe fn scan_tree(
    mut s: *mut crate::src::deflate::deflate_state,
    mut tree: *mut crate::src::deflate::ct_data,
    mut max_code: ::core::ffi::c_int,
) {
    let mut n: ::core::ffi::c_int = 0;
    let mut curlen: ::core::ffi::c_int = 0;
    let mut nextlen: ::core::ffi::c_int = (*tree).dl.len as ::core::ffi::c_int;
    let (mut prevlen, mut count, mut max_count, mut min_count) = initial_tree_run_state(nextlen);
    (*tree.wrapping_add(tree_next_cursor(max_code))).dl.len =
        0xffff as ::core::ffi::c_int as crate::zutil_h::ush;
    n = 0 as ::core::ffi::c_int;
    while n <= max_code {
        curlen = nextlen;
        nextlen = (*tree.wrapping_add(tree_next_cursor(n))).dl.len as ::core::ffi::c_int;
        let (incremented_count, step) =
            tree_run_step_after_increment(count, max_count, min_count, curlen, nextlen, prevlen);
        count = incremented_count;
        if let Some(action) = step.action {
            tally_scan_tree_action(&mut (*s).bl_tree, curlen, action);
        }
        count = step.count;
        prevlen = step.previous_len;
        max_count = step.max_count;
        min_count = step.min_count;
        n += 1;
    }
}

