    #[test]
    fn last_nonzero_bl_tree_rank_preserves_header_threshold() {
        let mut code_lengths = [0; BL_CODE_ORDER_LEN];
        assert_eq!(last_nonzero_bl_tree_rank(&code_lengths), 2);

        code_lengths[bl_code_index_at_rank(3)] = 1;
        assert_eq!(last_nonzero_bl_tree_rank(&code_lengths), 3);

        code_lengths[bl_code_index_at_rank(3)] = 0;
        code_lengths[bl_code_index_at_rank(7)] = 1;
        assert_eq!(last_nonzero_bl_tree_rank(&code_lengths), 7);
    }

    #[test]
    fn last_nonzero_bl_tree_rank_follows_deflate_code_order() {
        let mut code_lengths = [0; BL_CODE_ORDER_LEN];
        code_lengths[0] = 1;
        assert_eq!(last_nonzero_bl_tree_rank(&code_lengths), 3);

        code_lengths[15] = 1;
        assert_eq!(
            last_nonzero_bl_tree_rank(&code_lengths),
            crate::src::deflate::BL_CODES - 1
        );
    }

    #[test]
    fn bit_reversal_matches_deflate_widths() {
        for len in 1..=MAX_BITS {
            let mask = (1_u32 << len) - 1;
            for code in 0..=mask {
                let expected = code.reverse_bits() >> (u32::BITS - len as u32);
                assert_eq!(bi_reverse(code, len), expected, "code={code}, len={len}");
            }
        }

        assert_eq!(bi_reverse(0xdead_beef, 0), 0);
        assert_eq!(bi_reverse(0xdead_beef, -1), 0);
    }

    #[test]
    fn canonical_codes_skip_zero_lengths_and_reverse_assigned_codes() {
        let mut counts = [0; 16];
        counts[1] = 1;
        counts[2] = 2;

        let codes = canonical_codes_for_lengths(&[0, 1, 2, 2, 0], &counts);

        assert_eq!(codes, vec![None, Some(0), Some(1), Some(3), None]);
    }

    #[test]
    fn canonical_code_assignments_preserve_sparse_tree_indices() {
        let mut counts = [0; 16];
        counts[1] = 1;
        counts[2] = 2;

        let assignments = canonical_code_assignments(&[0, 1, 2, 2, 0], &counts);

        assert_eq!(assignments, vec![(1, 0), (2, 1), (3, 3)]);
    }

    #[test]
    fn canonical_code_assignment_updates_only_symbols_with_code_lengths() {
        let entry = crate::src::deflate::ct_data {
            fc: crate::src::deflate::C2Rust_Unnamed_1 { value: 99 },
            dl: crate::src::deflate::C2Rust_Unnamed_0 { dad: 0 },
        };
        let mut tree = [entry; 5];
        let mut counts = [0; 16];
        counts[1] = 1;
        counts[2] = 2;

        assign_canonical_codes(&mut tree, &[0, 1, 2, 2, 0], &counts);

        assert_eq!(tree.map(|entry| entry.fc.value), [99, 0, 1, 3, 99]);
    }

    #[test]
    fn tree_code_count_includes_the_maximum_code() {
        assert_eq!(tree_code_count(0), 1);
        assert_eq!(tree_code_count(285), 286);
        assert_eq!(
            tree_code_count(::core::ffi::c_int::MAX),
            ::core::ffi::c_int::MAX as usize + 1
        );
    }

    #[test]
    fn canonical_code_starts_follow_bit_length_counts() {
        let mut counts = [0; 16];
        counts[1] = 1;
        counts[2] = 2;
        counts[3] = 2;

        let codes = next_codes(&counts);
        assert_eq!(codes[1], 0);
        assert_eq!(codes[2], 2);
        assert_eq!(codes[3], 8);
        assert_eq!(codes[4], 20);
    }

    #[test]
    fn canonical_code_selection_increments_the_requested_length() {
        let mut codes = [0; 16];
        codes[0] = 4;
        codes[3] = 9;
        codes[MAX_BITS as usize] = 0xfffe;

        assert_eq!(next_code_for_len(&mut codes, 0), 4);
        assert_eq!(codes[0], 5);
        assert_eq!(next_code_for_len(&mut codes, 3), 9);
        assert_eq!(codes[3], 10);
        assert_eq!(next_code_for_len(&mut codes, MAX_BITS), 0xfffe);
        assert_eq!(codes[MAX_BITS as usize], 0xffff);
    }

