    #[test]
    fn bit_buffer_overflow_detects_exact_capacity_boundary() {
        assert!(!bit_buffer_would_overflow(
            crate::src::deflate::Buf_size - 5,
            5
        ));
        assert!(bit_buffer_would_overflow(
            crate::src::deflate::Buf_size - 4,
            5
        ));
        assert!(!bit_buffer_would_overflow(
            crate::src::deflate::Buf_size - 4,
            4
        ));
        assert!(bit_buffer_would_overflow(crate::src::deflate::Buf_size, 1));
    }

    #[test]
    fn bit_buffer_cores_emit_low_order_bytes() {
        let mut buffer = 0x1234;
        let mut valid = 16;
        assert_eq!(bi_flush_core(&mut buffer, &mut valid), (2, [0x34, 0x12]));
        assert_eq!((buffer, valid), (0, 0));

        let mut buffer = 0x1234;
        let mut valid = 9;
        assert_eq!(bi_flush_core(&mut buffer, &mut valid), (1, [0x34, 0x12]));
        assert_eq!((buffer, valid), (0x12, 1));

        let mut buffer = 0x1234;
        let mut valid = 9;
        assert_eq!(
            bi_windup_core(&mut buffer, &mut valid),
            (1, 2, [0x34, 0x12])
        );
        assert_eq!((buffer, valid), (0, 0));
    }

